    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 85-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding wound dehiscence, which of the following is most accurate in this setting?', '["It only occurs after the 3-month postoperative mark", "It is solely caused by the type of implant bearing surface used", "It is a rare complication seen almost exclusively in young patients", "Associated with early excessive flexion or poor nutrition", "It is completely preventable with prophylactic antibiotics"]'::jsonb, 3, 'Wound dehiscence is a known systemic complication following major joint arthroplasty. Specifically, it is associated with early excessive flexion or poor nutrition. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 70-year-old patient presents with severe shoulder pain and limited range of motion. Imaging and clinical evaluation confirm isolated humeral head osteonecrosis with preserved glenoid cartilage. Which of the following is the most appropriate surgical intervention?', '["Arthroscopic debridement and subacromial decompression", "Arthrodesis", "Anatomic Total Shoulder Arthroplasty (TSA)", "Reverse Total Shoulder Arthroplasty (rTSA)", "Hemiarthroplasty"]'::jsonb, 4, 'The primary indication for Hemiarthroplasty is isolated humeral head osteonecrosis with preserved glenoid cartilage. Anatomic TSA relies on an intact rotator cuff to maintain the humeral head centered on the glenoid. In contrast, rTSA is designed for cuffs that are severely deficient, utilizing the deltoid muscle to substitute for the rotator cuff.'),
    (v_topic_id, 'A 65-year-old patient is recovering from a total hip arthroplasty. According to current guidelines for patients at standard risk for deep vein thrombosis (DVT), what is the most appropriate duration for pharmacologic VTE prophylaxis?', '["At least 10 to 14 days, up to 35 days", "3 to 5 days", "3 months", "6 months", "24 to 48 hours"]'::jsonb, 0, 'Current orthopedic guidelines recommend extending pharmacologic venous thromboembolism (VTE) prophylaxis for a minimum of 10 to 14 days, and up to 35 days, following major joint replacement surgery (THA or TKA) to minimize the risk of DVT and pulmonary embolism.'),
    (v_topic_id, 'A 57-year-old patient is 8 weeks out from a primary total knee arthroplasty and complains of severe stiffness. Range of motion is 10 to 70 degrees. After failing aggressive physical therapy, what is the next most appropriate step in management?', '["Open arthrolysis and synovectomy", "Manipulation under anesthesia (MUA)", "Revision total knee arthroplasty", "Arthroscopic lysis of adhesions", "Long-term casting in extension"]'::jsonb, 1, 'Stiffness or arthrofibrosis after TKA is a frustrating complication. If aggressive physical therapy fails, the most appropriate next step within the first 2-3 months is typically a manipulation under anesthesia (MUA) to break up intra-articular adhesions and improve range of motion.'),
    (v_topic_id, 'A 57-year-old patient with end-stage post-traumatic ankle osteoarthritis is seeking surgical intervention. Which of the following patient profiles is considered the MOST ideal candidate for a total ankle arthroplasty (TAA) rather than an ankle arthrodesis?', '["A patient with severe avascular necrosis of the talus", "A patient with marked, uncorrectable varus deformity of the hindfoot", "A patient with a history of deep soft-tissue infection in the affected ankle", "An older, lower-demand patient with relatively good bone stock and normal hindfoot alignment", "A young, high-demand laborer with a physically strenuous job"]'::jsonb, 3, 'Total ankle arthroplasty is generally preferred for older, lower-demand individuals who wish to preserve range of motion. Contraindications typically include high physical demand, severe malalignment, prior infection, and poor bone stock (e.g., extensive AVN of the talus). Arthodesis remains the gold standard for high-demand patients.'),
    (v_topic_id, 'A 84-year-old patient is recovering from a total hip arthroplasty. According to current guidelines for patients at standard risk for deep vein thrombosis (DVT), what is the most appropriate duration for pharmacologic VTE prophylaxis?', '["3 to 5 days", "At least 10 to 14 days, up to 35 days", "6 months", "24 to 48 hours", "3 months"]'::jsonb, 1, 'Current orthopedic guidelines recommend extending pharmacologic venous thromboembolism (VTE) prophylaxis for a minimum of 10 to 14 days, and up to 35 days, following major joint replacement surgery (THA or TKA) to minimize the risk of DVT and pulmonary embolism.'),
    (v_topic_id, 'A 63-year-old patient is 8 weeks out from a primary total knee arthroplasty and complains of severe stiffness. Range of motion is 10 to 70 degrees. After failing aggressive physical therapy, what is the next most appropriate step in management?', '["Arthroscopic lysis of adhesions", "Revision total knee arthroplasty", "Long-term casting in extension", "Manipulation under anesthesia (MUA)", "Open arthrolysis and synovectomy"]'::jsonb, 3, 'Stiffness or arthrofibrosis after TKA is a frustrating complication. If aggressive physical therapy fails, the most appropriate next step within the first 2-3 months is typically a manipulation under anesthesia (MUA) to break up intra-articular adhesions and improve range of motion.'),
    (v_topic_id, 'A 56-year-old patient with end-stage post-traumatic ankle osteoarthritis is seeking surgical intervention. Which of the following patient profiles is considered the MOST ideal candidate for a total ankle arthroplasty (TAA) rather than an ankle arthrodesis?', '["A patient with severe avascular necrosis of the talus", "A patient with a history of deep soft-tissue infection in the affected ankle", "A young, high-demand laborer with a physically strenuous job", "A patient with marked, uncorrectable varus deformity of the hindfoot", "An older, lower-demand patient with relatively good bone stock and normal hindfoot alignment"]'::jsonb, 4, 'Total ankle arthroplasty is generally preferred for older, lower-demand individuals who wish to preserve range of motion. Contraindications typically include high physical demand, severe malalignment, prior infection, and poor bone stock (e.g., extensive AVN of the talus). Arthodesis remains the gold standard for high-demand patients.'),
    (v_topic_id, 'A 82-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Well below the stem tip. This is classified as Vancouver C. What is the most appropriate management?', '["Nonoperative management with protected weight-bearing", "ORIF with plate fixation", "Revision arthroplasty with a longer stem", "Revision arthroplasty with proximal femoral replacement", "ORIF with plates and cables"]'::jsonb, 1, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver C fractures occur Well below the stem tip and are best managed by ORIF with plate fixation.'),
    (v_topic_id, 'A 78-year-old patient undergoes a total hip arthroplasty via an anterior approach. Postoperatively, the patient has profound weakness in knee extension and decreased sensation over the anterior thigh. Which structure was most likely injured during the procedure?', '["Lateral femoral cutaneous nerve", "Obturator nerve", "Superior gluteal nerve", "Sciatic nerve", "Femoral nerve"]'::jsonb, 4, 'The femoral nerve provides motor innervation to the quadriceps (knee extension) and sensory innervation to the anterior thigh. It can be injured during an anterior approach to the hip due to retractor placement over the anterior rim of the acetabulum.'),
    (v_topic_id, 'A 79-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is well-fixed. This is classified as Vancouver B1. What is the most appropriate management?', '["Revision arthroplasty with proximal femoral replacement", "ORIF with intramedullary nailing", "Revision arthroplasty with a longer stem", "ORIF with plates and cables", "Nonoperative management with protected weight-bearing"]'::jsonb, 3, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B1 fractures occur Around the stem, stem is well-fixed and are best managed by ORIF with plates and cables.'),
    (v_topic_id, 'A 79-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Using a smaller femoral head size", "Maximizing soft tissue tension to prevent dislocation", "Aggressive reaming of the acetabulum", "Placing the femoral component in varus", "Excessive resection of the femoral neck"]'::jsonb, 1, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 69-year-old patient is recovering from a total hip arthroplasty. According to current guidelines for patients at standard risk for deep vein thrombosis (DVT), what is the most appropriate duration for pharmacologic VTE prophylaxis?', '["At least 10 to 14 days, up to 35 days", "24 to 48 hours", "3 months", "3 to 5 days", "6 months"]'::jsonb, 0, 'Current orthopedic guidelines recommend extending pharmacologic venous thromboembolism (VTE) prophylaxis for a minimum of 10 to 14 days, and up to 35 days, following major joint replacement surgery (THA or TKA) to minimize the risk of DVT and pulmonary embolism.'),
    (v_topic_id, 'A 70-year-old patient undergoes a total hip arthroplasty via an anterior approach. Postoperatively, the patient has profound weakness in knee extension and decreased sensation over the anterior thigh. Which structure was most likely injured during the procedure?', '["Sciatic nerve", "Superior gluteal nerve", "Femoral nerve", "Lateral femoral cutaneous nerve", "Obturator nerve"]'::jsonb, 2, 'The femoral nerve provides motor innervation to the quadriceps (knee extension) and sensory innervation to the anterior thigh. It can be injured during an anterior approach to the hip due to retractor placement over the anterior rim of the acetabulum.'),
    (v_topic_id, 'A 83-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding myocardial infarction, which of the following is most accurate in this setting?', '["Within the first 30 days postoperatively", "It is a rare complication seen almost exclusively in young patients", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark", "It is completely preventable with prophylactic antibiotics"]'::jsonb, 0, 'Myocardial infarction is a known systemic complication following major joint arthroplasty. Specifically, it is within the first 30 days postoperatively. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 73-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Trochanteric region. This is classified as Vancouver A. What is the most appropriate management?', '["Nonoperative or cerclage wires if widely displaced", "Revision arthroplasty with a longer stem", "Nonoperative management with protected weight-bearing", "ORIF with plates and cables", "Revision arthroplasty with proximal femoral replacement"]'::jsonb, 0, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver A fractures occur Trochanteric region and are best managed by Nonoperative or cerclage wires if widely displaced.'),
    (v_topic_id, 'A 62-year-old patient undergoes a total hip arthroplasty via an anterior approach. Postoperatively, the patient has profound weakness in knee extension and decreased sensation over the anterior thigh. Which structure was most likely injured during the procedure?', '["Femoral nerve", "Obturator nerve", "Sciatic nerve", "Lateral femoral cutaneous nerve", "Superior gluteal nerve"]'::jsonb, 0, 'The femoral nerve provides motor innervation to the quadriceps (knee extension) and sensory innervation to the anterior thigh. It can be injured during an anterior approach to the hip due to retractor placement over the anterior rim of the acetabulum.'),
    (v_topic_id, 'A 88-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding urinary tract infection, which of the following is most accurate in this setting?', '["It is completely preventable with prophylactic antibiotics", "It is a rare complication seen almost exclusively in young patients", "Associated with prolonged indwelling catheterization", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark"]'::jsonb, 2, 'Urinary tract infection is a known systemic complication following major joint arthroplasty. Specifically, it is associated with prolonged indwelling catheterization. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 77-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose. This is classified as Vancouver B2. What is the most appropriate management?', '["Revision arthroplasty with a longer stem", "Revision arthroplasty with proximal femoral replacement", "ORIF with plates and cables", "Nonoperative management with protected weight-bearing", "ORIF with intramedullary nailing"]'::jsonb, 0, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B2 fractures occur Around the stem, stem is loose and are best managed by Revision arthroplasty with a longer stem.'),
    (v_topic_id, 'A 71-year-old patient undergoes a total hip arthroplasty via an anterior approach. Postoperatively, the patient has profound weakness in knee extension and decreased sensation over the anterior thigh. Which structure was most likely injured during the procedure?', '["Sciatic nerve", "Obturator nerve", "Superior gluteal nerve", "Lateral femoral cutaneous nerve", "Femoral nerve"]'::jsonb, 4, 'The femoral nerve provides motor innervation to the quadriceps (knee extension) and sensory innervation to the anterior thigh. It can be injured during an anterior approach to the hip due to retractor placement over the anterior rim of the acetabulum.'),
    (v_topic_id, 'A 82-year-old patient presents with thigh pain 12 years after a total hip arthroplasty. Radiographs show eccentric wear of the polyethylene liner and focal osteolytic lesions around the acetabular and femoral components without signs of acute infection. What is the most likely underlying pathophysiologic mechanism?', '["Macrophage response to particulate wear debris", "Type IV hypersensitivity reaction to metal ions", "Stress shielding of the proximal femur", "Galvanic corrosion of the modular neck", "Low-grade chronic periprosthetic infection"]'::jsonb, 0, 'Particle disease (aseptic loosening) is caused by the generation of particulate wear debris (commonly polyethylene). Macrophages phagocytose this debris and release inflammatory cytokines (e.g., TNF-alpha, IL-1, IL-6), leading to increased osteoclast activity and subsequent osteolysis.'),
    (v_topic_id, 'A 79-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Well below the stem tip. This is classified as Vancouver C. What is the most appropriate management?', '["Revision arthroplasty with a longer stem", "ORIF with plate fixation", "ORIF with plates and cables", "Revision arthroplasty with proximal femoral replacement", "Nonoperative management with protected weight-bearing"]'::jsonb, 1, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver C fractures occur Well below the stem tip and are best managed by ORIF with plate fixation.'),
    (v_topic_id, 'A 81-year-old male undergoes a total hip arthroplasty via a standard anterior approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Extension, abduction, and internal rotation", "Extension and internal rotation", "Flexion, adduction, and external rotation", "Flexion, abduction, and external rotation", "Extension and external rotation"]'::jsonb, 4, 'In a anterior approach to the hip, the typical position of instability causing dislocation is extension and external rotation. The Lateral femoral cutaneous nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 78-year-old patient presents with vague, progressive shoulder pain 1 year after an anatomic total shoulder arthroplasty. Inflammatory markers are minimally elevated, and there is no frank purulence on aspiration. Intraoperative cultures eventually grow a slow-growing anaerobic Gram-positive bacillus. Which organism is most likely responsible?', '["Pseudomonas aeruginosa", "Staphylococcus epidermidis", "Streptococcus pyogenes", "Staphylococcus aureus", "Cutibacterium acnes"]'::jsonb, 4, 'Cutibacterium (formerly Propionibacterium) acnes is a common skin flora around the shoulder and a frequent cause of indolent, chronic periprosthetic joint infections following shoulder arthroplasty. It often requires prolonged incubation (up to 14 days) to grow in culture.'),
    (v_topic_id, 'A 74-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding urinary tract infection, which of the following is most accurate in this setting?', '["It is a rare complication seen almost exclusively in young patients", "Associated with prolonged indwelling catheterization", "It is completely preventable with prophylactic antibiotics", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark"]'::jsonb, 1, 'Urinary tract infection is a known systemic complication following major joint arthroplasty. Specifically, it is associated with prolonged indwelling catheterization. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 71-year-old patient presents with vague, progressive shoulder pain 1 year after an anatomic total shoulder arthroplasty. Inflammatory markers are minimally elevated, and there is no frank purulence on aspiration. Intraoperative cultures eventually grow a slow-growing anaerobic Gram-positive bacillus. Which organism is most likely responsible?', '["Staphylococcus aureus", "Streptococcus pyogenes", "Cutibacterium acnes", "Pseudomonas aeruginosa", "Staphylococcus epidermidis"]'::jsonb, 2, 'Cutibacterium (formerly Propionibacterium) acnes is a common skin flora around the shoulder and a frequent cause of indolent, chronic periprosthetic joint infections following shoulder arthroplasty. It often requires prolonged incubation (up to 14 days) to grow in culture.'),
    (v_topic_id, 'A 65-year-old male with a history of ankylosing spondylitis undergoes a total hip arthroplasty. He is at high risk for developing postoperative heterotopic ossification. Which of the following is an effective prophylactic measure?', '["Postoperative indomethacin or single-dose radiation therapy", "Prolonged immobilization in a spica cast", "Postoperative prophylactic enoxaparin", "High-dose systemic corticosteroids for 2 weeks", "Intravenous bisphosphonates immediately post-op"]'::jsonb, 0, 'Heterotopic ossification is a common complication after THA, especially in patients with a history of it, ankylosing spondylitis, or hypertrophic osteoarthritis. Prophylaxis typically involves a course of oral NSAIDs (like indomethacin) or a single fraction of localized radiation therapy.'),
    (v_topic_id, 'A 76-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is well-fixed. This is classified as Vancouver B1. What is the most appropriate management?', '["Nonoperative management with protected weight-bearing", "Revision arthroplasty with proximal femoral replacement", "ORIF with plates and cables", "Revision arthroplasty with a longer stem", "ORIF with intramedullary nailing"]'::jsonb, 2, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B1 fractures occur Around the stem, stem is well-fixed and are best managed by ORIF with plates and cables.'),
    (v_topic_id, 'A 77-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Excessive resection of the femoral neck", "Placing the femoral component in varus", "Maximizing soft tissue tension to prevent dislocation", "Using a smaller femoral head size", "Aggressive reaming of the acetabulum"]'::jsonb, 2, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 74-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Maximizing soft tissue tension to prevent dislocation", "Placing the femoral component in varus", "Using a smaller femoral head size", "Aggressive reaming of the acetabulum", "Excessive resection of the femoral neck"]'::jsonb, 0, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 61-year-old patient with end-stage post-traumatic ankle osteoarthritis is seeking surgical intervention. Which of the following patient profiles is considered the MOST ideal candidate for a total ankle arthroplasty (TAA) rather than an ankle arthrodesis?', '["A patient with marked, uncorrectable varus deformity of the hindfoot", "An older, lower-demand patient with relatively good bone stock and normal hindfoot alignment", "A patient with a history of deep soft-tissue infection in the affected ankle", "A patient with severe avascular necrosis of the talus", "A young, high-demand laborer with a physically strenuous job"]'::jsonb, 1, 'Total ankle arthroplasty is generally preferred for older, lower-demand individuals who wish to preserve range of motion. Contraindications typically include high physical demand, severe malalignment, prior infection, and poor bone stock (e.g., extensive AVN of the talus). Arthodesis remains the gold standard for high-demand patients.'),
    (v_topic_id, 'A 73-year-old patient is 8 weeks out from a primary total knee arthroplasty and complains of severe stiffness. Range of motion is 10 to 70 degrees. After failing aggressive physical therapy, what is the next most appropriate step in management?', '["Long-term casting in extension", "Revision total knee arthroplasty", "Open arthrolysis and synovectomy", "Arthroscopic lysis of adhesions", "Manipulation under anesthesia (MUA)"]'::jsonb, 4, 'Stiffness or arthrofibrosis after TKA is a frustrating complication. If aggressive physical therapy fails, the most appropriate next step within the first 2-3 months is typically a manipulation under anesthesia (MUA) to break up intra-articular adhesions and improve range of motion.'),
    (v_topic_id, 'A 70-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose. This is classified as Vancouver B2. What is the most appropriate management?', '["ORIF with plates and cables", "Nonoperative management with protected weight-bearing", "Revision arthroplasty with a longer stem", "Revision arthroplasty with proximal femoral replacement", "ORIF with intramedullary nailing"]'::jsonb, 2, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B2 fractures occur Around the stem, stem is loose and are best managed by Revision arthroplasty with a longer stem.'),
    (v_topic_id, 'A 68-year-old patient undergoes an anatomic total shoulder arthroplasty. During the deltopectoral approach, care must be taken to protect the nerve that innervates the deltoid and teres minor. Injury to this nerve most commonly occurs at which surgical step?', '["Humeral head resection", "Glenoid preparation", "Inferior capsular release", "Biceps tenodesis", "Subscapularis tenotomy"]'::jsonb, 2, 'The axillary nerve innervates the deltoid and teres minor. It travels close to the inferior capsule of the shoulder joint and is at greatest risk of injury during inferior capsular release in shoulder arthroplasty.'),
    (v_topic_id, 'A 83-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose. This is classified as Vancouver B2. What is the most appropriate management?', '["Nonoperative management with protected weight-bearing", "Revision arthroplasty with a longer stem", "ORIF with plates and cables", "Revision arthroplasty with proximal femoral replacement", "ORIF with intramedullary nailing"]'::jsonb, 1, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B2 fractures occur Around the stem, stem is loose and are best managed by Revision arthroplasty with a longer stem.'),
    (v_topic_id, 'A 76-year-old patient presents with severe shoulder pain and limited range of motion. Imaging and clinical evaluation confirm severe 4-part proximal humerus fracture in an 80-year-old. Which of the following is the most appropriate surgical intervention?', '["Hemiarthroplasty", "Anatomic Total Shoulder Arthroplasty (TSA)", "Reverse Total Shoulder Arthroplasty (rTSA)", "Arthrodesis", "Arthroscopic debridement and subacromial decompression"]'::jsonb, 2, 'The primary indication for Reverse Total Shoulder Arthroplasty (rTSA) is severe 4-part proximal humerus fracture in an 80-year-old. Anatomic TSA relies on an intact rotator cuff to maintain the humeral head centered on the glenoid. In contrast, rTSA is designed for cuffs that are severely deficient, utilizing the deltoid muscle to substitute for the rotator cuff.'),
